import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import FormControlGroup from "../../functional-components/form-control/form-control-group";
import {
	customErrorValidityState,
	validValidityState,
	valueMissingValidityState,
} from "../../utils/form";
import { hasSlot } from "../../utils/slot";

/**
 * @since 1.0.0
 * @status stable
 *
 * @slot The default slot where `<hbr-radio-button>` element is placed..
 * @slot label - The view switcher label. Required for proper accessibility. Alternatively, you can use the `label` attribute.
 * @slot label-suffix - The radio group label-suffix.
 * @slot help-text - The radio group help-text.
 *
 * @part base - The component's base wrapper.
 * @part label - The label wrapper.
 * @part children - The wrapper of the default slot.
 * @part button-group - The button group that wraps radio buttons.
 * @part button-group__base - The button group's `base` part.
 * @part help-text - The help-text wrapper.
 * @part asterisk - The asterisk in the label if required is true.
 * @part legend - The legend element.
 */

@Component({
	tag: "hbr-view-switcher",
	styleUrl: "view-switcher.scss",
	shadow: true,
})
export class ViewSwitcher {
	@Element() host: HTMLHbrViewSwitcherElement;
	@State() hasLabel = false;
	@State() hasHelpTextSlot = false;
	@State() private errorMessage = "";
	@State() defaultValue = "";
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;

	/** Hides the fieldset and legend that is used by view switcher. The label will still be read by screen readers. */
	@Prop() noFieldset = false;

	/** The view switcher label. Required for proper accessibility. Alternatively, you can use the label slot. */
	@Prop() label = "";

	/** The view switcher helpText that works with hbr form control */
	@Prop() helpText = "";

	/** The view switcher helpText id that works with hbr form control */
	@Prop() helpTextId = "";

	/** Set to true to indicate that the user must select a value before submitting a hbr form. */
	@Prop({ reflect: true }) required = false;

	/** Set to true to disable the view switcher. */
	@Prop({ reflect: true }) disabled = false;

	/** Set to true to display the view switcher with an error red label in a hbr form */
	@Prop() error = false;

	/** The view switcher's size. */
	@Prop({ reflect: true }) size: "xsmall" | "small" | "medium" | "large" =
		"medium";

	/** The current value of the view switcher, submitted as a name/value pair with form data. */
	@Prop({ reflect: true, mutable: true }) value = "";

	private customValidityMessage = "";
	private validationTimeout: number;

	defaultSlot: HTMLSlotElement;
	validationInput: HTMLInputElement;

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("value")
	handleValueChange() {
		const radios = this.getAllRadios();
		radios.forEach((radio) => {
			radio.checked = radio.value === this.value;
		});
	}

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the control receives input. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Gets the validity state object */
	get validity() {
		const isRequiredAndEmpty = this.required && !this.value;
		const hasCustomValidityMessage = this.customValidityMessage !== "";

		if (hasCustomValidityMessage) {
			return customErrorValidityState;
		}
		if (isRequiredAndEmpty) {
			return valueMissingValidityState;
		}

		return validValidityState;
	}

	/** Gets the validation message */
	get validationMessage() {
		const isRequiredAndEmpty = this.required && !this.value;
		const hasCustomValidityMessage = this.customValidityMessage !== "";

		if (hasCustomValidityMessage) {
			return this.customValidityMessage;
		}
		if (isRequiredAndEmpty) {
			return this.validationInput.validationMessage;
		}

		return "";
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleRadioClick = this.handleRadioClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	componentDidLoad() {
		this.validationInput = this.host.shadowRoot.querySelector(
			".radio-group__validation-input",
		);
		this.handleSlotChange();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	handleSlotChange() {
		this.hasLabel = hasSlot(this.host, "label");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");

		const radios = this.getAllRadios();
		radios.forEach((radio) => {
			radio.checked = radio.value === this.value;
		});

		if (!radios.some((radio) => radio.checked)) {
			// biome-ignore lint/style/noNonNullAssertion: <explanation>
			const buttonRadio = radios[0].shadowRoot?.querySelector("button")!;
			if (buttonRadio) buttonRadio.tabIndex = 0;
		}

		const buttonGroup = this.host.shadowRoot?.querySelector(
			"hbr-button-group",
		) as HTMLHbrButtonGroupElement;
		if (buttonGroup) {
			buttonGroup.disableRole = true;
		}
	}

	private getAllRadios() {
		return [
			...this.host.querySelectorAll<HTMLHbrRadioButtonElement>(
				"hbr-radio-button",
			),
		];
	}

	private handleRadioClick(event: MouseEvent) {
		const target = (
			event.target as HTMLElement
		)?.closest<HTMLHbrRadioButtonElement>("hbr-radio-button");

		if (!target || target.disabled) {
			return;
		}

		const radios = this.getAllRadios();
		const oldValue = this.value;

		this.value = target.value;
		radios.forEach((radio) => {
			radio.checked = radio === target;
		});

		if (this.value !== oldValue) {
			this.hbrChange.emit();
			this.hbrInput.emit();
		}
	}

	private handleKeyDown(event: KeyboardEvent) {
		if (
			!["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", " "].includes(
				event.key,
			)
		) {
			return;
		}

		const radios = this.getAllRadios().filter((radio) => !radio.disabled);
		const checkedRadio = radios.find((radio) => radio.checked) ?? radios[0];
		const incr =
			event.key === " "
				? 0
				: ["ArrowUp", "ArrowLeft"].includes(event.key)
				  ? -1
				  : 1;
		const oldValue = this.value;
		let index = radios.indexOf(checkedRadio) + incr;

		if (index < 0) {
			index = radios.length - 1;
		}

		if (index > radios.length - 1) {
			index = 0;
		}

		this.getAllRadios().forEach((radio) => {
			radio.checked = false;
		});

		this.value = radios[index].value;
		radios[index].checked = true;
		radios[index].shadowRoot?.querySelector("button")?.focus();

		if (this.value !== oldValue) {
			this.hbrChange.emit();
			this.hbrInput.emit();
		}

		event.preventDefault();
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		const isValid = this.validity.valid;

		this.errorMessage =
			this.customValidityMessage || isValid
				? ""
				: this.validationInput.validationMessage;
		if (this.validationInput) this.validationInput.hidden = true;
		clearTimeout(this.validationTimeout);

		if (!isValid && this.validationInput) {
			// Show the browser's constraint validation message
			this.validationInput.hidden = false;
			this.validationInput.reportValidity();
			this.validationTimeout = setTimeout(() => {
				this.validationInput.hidden = true;
			}, 10000) as unknown as number;
		}

		return isValid;
	}

	/** Sets a custom validation message. Pass an empty string to restore validity. */
	@Method()
	async setCustomValidity(message = "") {
		this.customValidityMessage = message;
		this.errorMessage = message;
		this.validationInput.setCustomValidity(message);
	}

	render() {
		return (
			<FormControlGroup
				hasHelpTextSlot={this.hasHelpTextSlot}
				label={this.label}
				hasError={this.error}
				size={this.size}
				hasLabelSlot={this.hasLabel}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				helpTextId={this.helpTextId}
				helpText={this.helpText}
				isRequired={this.required}
				isDisabled={this.disabled}
				noFieldset={this.noFieldset}
				// role={"presentation"}
				errorMessage={this.errorMessage}
			>
				<hbr-button-group
					part="button-group"
					exportparts="base:button-group__base"
					onClick={this.handleRadioClick}
					onKeyDown={this.handleKeyDown}
					disabled={this.disabled}
				>
					<slot onSlotchange={this.handleSlotChange} />
				</hbr-button-group>
			</FormControlGroup>
		);
	}
}
